#!/usr/bin/env python3
"""Own read-only final join and split identity supplement, no other sources."""
import pathlib,collections
import belief_gap_v2_adversarial_audit as a
rs=a.load(a.CAND);tr=[r for r in rs if r['split']=='train'];dv=[r for r in rs if r['split']=='dev_challenge'];frozen=[a.OUT/'belief-gap-v2.input_predictions.jsonl',a.OUT/'belief-gap-v2.first_judgments.jsonl',a.OUT/'belief-gap-v2.jsonl'];sets={}
