    sets[split]={'source_family_keys':{r['source_family_key'] for r in xs},'semantic_parent_ids':{r['semantic_parent_id'] for r in xs},'semantic_family_ids':{r['semantic_family_id'] for r in xs},'world_ids':{w['world_id'] for r in xs for w in r['semantic_task']['worlds']},'exact_task_hashes':{a.digest(r['semantic_task']) for r in xs},'decoded_table_hashes':{a.digest(a.normalized(r)['worlds']) for r in xs}}
