final=a.load(frozen[-1]);a.require(len(final)==1728 and {r['reviewer_execution_id'] for r in final}=={a.EXECUTION},'Actual IDs/count');mapping={r['sample_id']:r['record_hash'] for r in rs};a.require(all(mapping[r['sample_id']]==r['record_hash'] for r in final),'Final exact hashes')
report={'reviewer_execution_id':a.EXECUTION,'batch':a.BATCH,'status':'completed','supplement_scope':'Final exact receipt/source integrity and actual train/dev identity-set checks only; frozen predictions and first/final decisions unchanged. Shared unweighted cyclic motif remains documented separately.','candidate_sha256':a.sha(a.CAND),'frozen_evidence_hashes':{str(p.relative_to(a.ROOT)):a.sha(p) for p in frozen},'source_ids_per_split':{split:{k:len(v) for k,v in buckets.items()} for split,buckets in sets.items()},'actual_cross_split_identity_intersections':checks,'receipt_execution_ids':[a.EXECUTION],'final_decisions':dict(collections.Counter(r['decision'] for r in final)),'script_sha256':a.sha(pathlib.Path(__file__)),'helper_program_sha256':a.sha(pathlib.Path(a.__file__))}
